const __pageData = JSON.parse('{"title":"Vladimir Putin","description":"","frontmatter":{"title":"Vladimir Putin","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["russia","ukraine","nato","geopolitics"],"sources":["raw/a-bright-red-line.md","raw/a-gateway-to-a-new-world-of-cooperation.md","raw/a-virus-or-a-metaphor.md","raw/are-cbdcs-the-path-to-fear-or-freedom.md","raw/avoiding-wwiii.md","raw/badlands-blitz-episode-17.md","raw/badlands-brief-144.md","raw/badlands-brief-174.md","raw/badlands-brief-245.md","raw/badlands-brief-2b2.md","raw/badlands-brief-311.md","raw/badlands-brief-50d.md","raw/badlands-brief-5a2.md","raw/badlands-brief-6bf.md","raw/badlands-brief-618.md","raw/badlands-brief-739.md","raw/badlands-brief-70c.md","raw/badlands-brief-708.md","raw/badlands-brief-835.md","raw/badlands-brief-990.md","raw/badlands-brief-9f2.md","raw/badlands-news-brief-017.md","raw/badlands-news-brief-006.md","raw/badlands-news-brief-050.md","raw/badlands-news-brief-054.md","raw/badlands-news-brief-065.md","raw/badlands-news-brief-060.md","raw/badlands-news-brief-01d.md","raw/badlands-news-brief-051.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-09e.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-0db.md","raw/badlands-news-brief-0e0.md","raw/badlands-news-brief-0ef.md","raw/badlands-news-brief-109.md","raw/badlands-news-brief-125.md","raw/badlands-news-brief-120.md","raw/badlands-news-brief-153.md","raw/badlands-news-brief-12a.md","raw/badlands-news-brief-143.md","raw/badlands-news-brief-169.md","raw/badlands-news-brief-1e2.md","raw/badlands-news-brief-1f2.md","raw/badlands-news-brief-228.md","raw/badlands-news-brief-1e6.md","raw/badlands-news-brief-24e.md","raw/badlands-news-brief-26c.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-264.md","raw/badlands-news-brief-28e.md","raw/badlands-news-brief-2a0.md","raw/badlands-news-brief-2ad.md","raw/badlands-news-brief-2d5.md","raw/badlands-news-brief-316.md","raw/badlands-news-brief-324.md","raw/badlands-news-brief-32d.md","raw/badlands-news-brief-378.md","raw/badlands-news-brief-3a5.md","raw/badlands-news-brief-3b2.md","raw/badlands-news-brief-421.md","raw/badlands-news-brief-471.md","raw/badlands-news-brief-4a6.md","raw/badlands-news-brief-4cf.md","raw/badlands-news-brief-50f.md","raw/badlands-news-brief-533.md","raw/badlands-news-brief-545.md","raw/badlands-news-brief-565.md","raw/badlands-news-brief-58c.md","raw/badlands-news-brief-592.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-5c8.md","raw/badlands-news-brief-5ec.md","raw/badlands-news-brief-6b1.md","raw/badlands-news-brief-6aa.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-6e6.md","raw/badlands-news-brief-711.md","raw/badlands-news-brief-747.md","raw/badlands-news-brief-683.md","raw/badlands-news-brief-762.md","raw/badlands-news-brief-7bb.md","raw/badlands-news-brief-7bf.md","raw/badlands-news-brief-7b8.md","raw/badlands-news-brief-85c.md","raw/badlands-news-brief-881.md","raw/badlands-news-brief-860.md","raw/badlands-news-brief-8a9.md","raw/badlands-news-brief-8c5.md","raw/badlands-news-brief-8d8.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/vladimir-putin.md","filePath":"entities/vladimir-putin.md","lastUpdated":null}');
